_EMOJI_TAG_RE = re.compile(r"<emoji\s+id=[\"\']\d+[\"\']>.*?</emoji>", re.I | re.S)
_BLOCKQUOTE_RE = re.compile(r"</?blockquote(?:\s+[^>]*)?>", re.I)


def _clean_text(text: str) -> str:
    return str(text or "").strip()


def decorate_text(text: str, emoji_count: int = 3) -> str:
    """Apply the bot's global quote + random premium-emoji style once."""
    text = _clean_text(text)
    if not text:
        return text

    # Do not keep stacking decorators when a message is edited.
    already_emoji = bool(_EMOJI_TAG_RE.search(text))
    has_quote = bool(_BLOCKQUOTE_RE.search(text))

    if not has_quote:
        text = f"<blockquote>{text}</blockquote>"

    if already_emoji:
        return text

    count = max(1, int(emoji_count))
    prefix = " ".join(
        f'<emoji id="{random.choice(PREMIUM_EMOJIS)}">✨</emoji>'
        for _ in range(count)
    )
    suffix = f'<emoji id="{random.choice(PREMIUM_EMOJIS)}">✨</emoji>'
    return f"{prefix} {text} {suffix}"


def decorate_caption(caption: str) -> str:
    return decorate_text(caption) if caption else caption
